page.css:
/* ==========================================================================
   LTVCR - site stylesheet (single source of truth)
   Loaded once, site wide. Edit here and every page, the header and the footer
   all update together. Do not paste a second copy anywhere.
   ========================================================================== */


/* ==========================================================================
   Long Term Van & Car Rentals - Home Page V3
   LTVCR brand colours taken from the logo (orange + black)
   Wide container, scroll animations
   ========================================================================== */

:root, .ltvcr-root{
  --brand:#0568eb;
  --brand-d:#0450c4;
  --brand-l:#4d94ff;
  --brand-soft:#e9f1ff;
  --brand-soft-2:#d4e5ff;
  --ink:#07182f;
  --ink-2:#14233c;
  --ink-3:#233450;
  --muted:#5e6a7d;
  --muted-2:#8893a5;
  --line:#e3e9f2;
  --line-2:#eef2f9;
  --cream:#eef4ff;
  --soft:#f6f9fd;
  --white:#fff;
  --r-xl:38px;
  --r-lg:26px;
  --r-md:18px;
  --r-sm:12px;
  --pill:100px;
  --gut:clamp(16px,3.6vw,66px);
  --maxw:1620px;
  --maxw-wide:1820px;
  --sh:0 14px 38px rgba(7,18,36,.09);
  --sh-lg:0 30px 80px rgba(7,18,36,.17);
  --ease:cubic-bezier(.22,.61,.36,1);
  --ease-out:cubic-bezier(.16,1,.3,1);
}

*{box-sizing:border-box}
.ltvcr-root,.ltvcr-root *,.ltvcr-root *::before,.ltvcr-root *::after{box-sizing:border-box}
html{scroll-behavior:smooth;overflow-x:clip}
.ltvcr-root{font-family:'DM Sans',system-ui,-apple-system,Arial,sans-serif;color:var(--ink-2);font-size:17px;line-height:1.62;-webkit-font-smoothing:antialiased}
/* page content overflows on purpose (the CTA van, the decorative glows). Keep the
   clip on the wrapper so it holds even where html/body rules are scoped away. */
.ltvcr-root.ltvcr-page,.ltvcr-root.ltvcr-chrome{overflow-x:clip}
body{
  margin:0;
  font-family:'DM Sans',system-ui,-apple-system,Arial,sans-serif;
  color:var(--ink-2);
  background:var(--white);
  font-size:17px;
  line-height:1.62;
  -webkit-font-smoothing:antialiased;
  overflow-x:clip;
}
img{max-width:100%;display:block;height:auto}
svg{width:18px;height:18px;flex-shrink:0}
a{color:var(--brand);text-decoration:none}
p{margin:0 0 1rem}
h1,h2,h3,h4,h5{
  font-family:'Epilogue','DM Sans',Arial,sans-serif;
  color:var(--ink);line-height:1.06;letter-spacing:-.028em;font-weight:700;margin:0 0 .5em;
}
h1{font-size:clamp(2.4rem,4.6vw,4.6rem)}
h2{font-size:clamp(2rem,3.6vw,3.5rem)}
h3{font-size:clamp(1.18rem,1.5vw,1.45rem);letter-spacing:-.016em}
h4{font-size:1.08rem;letter-spacing:-.01em}

.wrap{max-width:var(--maxw);margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.wrap-wide{max-width:var(--maxw-wide);margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.sec{padding-top:clamp(60px,7vw,120px);padding-bottom:clamp(60px,7vw,120px)}
.center{text-align:center}
.lead{font-size:clamp(1rem,1.1vw,1.12rem);color:var(--muted);max-width:66ch;margin-bottom:0}
.center .lead{margin-left:auto;margin-right:auto}
.sec-head{max-width:820px}
.sec-head.center{margin-left:auto;margin-right:auto}

/* ---------- Eyebrow ---------- */
.eyebrow{
  display:inline-flex;align-items:flex-start;gap:9px;
  font-family:'Epilogue',Arial,sans-serif;font-weight:600;
  font-size:1rem;letter-spacing:.005em;color:var(--brand);margin:0 0 18px;
}
.eyebrow::before{
  content:"";width:16px;height:16px;flex:0 0 16px;margin-top:4px;background:currentColor;
  -webkit-mask:var(--ast) center/100% 100% no-repeat;
  mask:var(--ast) center/100% 100% no-repeat;
}
:root{
  --ast:url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Cpath fill='%23000' d='M10.5 1h3v7l5-4.9 2.1 2.1-4.9 5h7v3h-7l4.9 5-2.1 2.1-5-4.9v7h-3v-7l-5 4.9L3.4 19.3l4.9-5h-7v-3h7l-4.9-5L5.5 4.2l5 4.9z'/%3E%3C/svg%3E");
}
.eyebrow.on-dark{color:var(--brand-l)}
.center .eyebrow,.eyebrow.center{justify-content:center}

/* ---------- Illustrative icons ----------
   Each chip sets --ic (line), --ic-a (accent) and --ic-bg (the knockout colour
   used behind badge glyphs), so the whole scene inverts on hover. */
.ic{width:100%;height:100%;display:block}
[class$="-ico"]{--ic:var(--ink);--ic-a:var(--brand);--ic-bg:var(--brand-soft)}

/* ---------- Buttons ---------- */
.btn{
  cursor:pointer;
  display:inline-flex;align-items:center;justify-content:center;gap:10px;
  font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:1rem;
  padding:16px 32px;border-radius:var(--pill);
  background:linear-gradient(135deg,#2d85ff 0%,var(--brand) 52%,#0345b0 100%);
  color:#fff;border:1px solid rgba(255,255,255,.18);
  box-shadow:0 10px 26px rgba(5,104,235,.3), inset 0 1px 0 rgba(255,255,255,.26);
  cursor:pointer;transition:.34s var(--ease);white-space:nowrap;position:relative;overflow:hidden;
  isolation:isolate;text-shadow:0 1px 1px rgba(120,30,0,.22);
}
.btn::after{
  content:"";position:absolute;inset:0;z-index:-1;
  background:linear-gradient(135deg,#143a6e 0%,var(--ink) 100%);
  transform:translateY(102%);transition:transform .44s var(--ease-out);
}
/* shine sweep */
.btn::before{
  content:"";position:absolute;top:0;bottom:0;left:-80%;width:55%;z-index:0;pointer-events:none;
  background:linear-gradient(100deg,rgba(255,255,255,0) 0%,rgba(255,255,255,.42) 50%,rgba(255,255,255,0) 100%);
  transform:skewX(-18deg);transition:left .7s var(--ease-out);
}
.btn:hover::before{left:135%}
.btn:hover::after{transform:translateY(0)}
.btn:hover{
  color:#fff;border-color:rgba(255,255,255,.14);transform:translateY(-2px);
  box-shadow:0 16px 36px rgba(7,18,36,.3), inset 0 1px 0 rgba(255,255,255,.18);
}
.btn:active{transform:translateY(0)}
.btn > *{position:relative;z-index:1}

/* header / hero headline CTA: keeps a slow glow so the eye lands on it */
.btn-glow{animation:glowPulse 3.2s ease-in-out infinite}
@keyframes glowPulse{
  0%,100%{box-shadow:0 10px 26px rgba(5,104,235,.3), 0 0 0 0 rgba(5,104,235,.42), inset 0 1px 0 rgba(255,255,255,.26)}
  50%{box-shadow:0 12px 30px rgba(5,104,235,.42), 0 0 0 9px rgba(5,104,235,0), inset 0 1px 0 rgba(255,255,255,.26)}
}
.btn-glow::before{animation:shineLoop 4.6s var(--ease-out) infinite}
@keyframes shineLoop{0%,62%{left:-80%}92%,100%{left:135%}}
.btn-glow:hover{animation:none}
@media (prefers-reduced-motion:reduce){.btn-glow,.btn-glow::before{animation:none}}
.btn svg{width:17px;height:17px}
.btn-dark{background:linear-gradient(135deg,#143a6e,var(--ink));border-color:rgba(255,255,255,.14);box-shadow:0 10px 26px rgba(7,18,36,.26),inset 0 1px 0 rgba(255,255,255,.12);text-shadow:none}
.btn-dark::after{background:linear-gradient(135deg,#2d85ff,var(--brand))}
.btn-dark:hover{border-color:var(--brand)}
.btn-light{background:#fff;border-color:#fff;color:var(--ink);box-shadow:0 10px 26px rgba(7,18,36,.14);text-shadow:none}
.btn-light::after{background:linear-gradient(135deg,#2d85ff,var(--brand))}
.btn-light:hover{color:#fff;border-color:var(--brand)}
.btn-line{background:transparent;border-color:var(--line);color:var(--ink);box-shadow:none;text-shadow:none}
.btn-line::after{background:linear-gradient(135deg,#143a6e,var(--ink))}
.btn-line::before{display:none}
.btn-line:hover{color:#fff;border-color:var(--ink)}
.btn-line-light{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.42);color:#fff;backdrop-filter:blur(6px);box-shadow:none;text-shadow:none}
.btn-line-light::after{background:#fff}
.btn-line-light:hover{color:var(--ink);border-color:#fff}
.btn-line-light:hover{color:var(--ink);border-color:#fff}
.btn-sm{padding:11px 22px;font-size:.92rem}
/* arrow travels inside the pill, so no separate circle button */
.btn-arrow{padding-right:8px;gap:14px}
.btn-arrow .btn-ico{
  width:38px;height:38px;border-radius:50%;background:#fff;color:var(--brand);
  display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;
  transition:.38s var(--ease);box-shadow:0 2px 8px rgba(7,18,36,.16);
}
.btn-arrow .btn-ico svg{width:16px;height:16px;transition:.38s var(--ease)}
.btn-arrow:hover .btn-ico{transform:rotate(45deg)}
.btn-arrow.btn-sm{padding:7px 8px 7px 22px;gap:12px}
.btn-arrow.btn-sm .btn-ico{width:34px;height:34px}
.btn-arrow.btn-sm .btn-ico svg{width:14px;height:14px}
.btn-arrow.btn-lg{padding:9px 9px 9px 36px;gap:16px}
.btn-arrow.btn-lg .btn-ico{width:48px;height:48px}
.btn-arrow.btn-lg .btn-ico svg{width:18px;height:18px}
.btn-line .btn-ico,.btn-line-light .btn-ico{background:var(--brand);color:#fff}

/* Google reviews link */
.btn-google{
  display:inline-flex;align-items:center;gap:11px;background:#fff;color:var(--ink);
  border:1px solid var(--line);border-radius:var(--pill);padding:12px 24px;
  font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:.95rem;
  transition:.32s var(--ease);box-shadow:0 6px 18px rgba(7,18,36,.07);white-space:nowrap;
}
.btn-google:hover{transform:translateY(-2px);box-shadow:0 12px 28px rgba(7,18,36,.13);border-color:#fff}
.btn-google .g-mark{width:19px;height:19px;flex-shrink:0}
.btn-google .g-stars{display:inline-flex;gap:2px}
.btn-google .g-stars svg{width:13px;height:13px;color:#fbbc04}
.btn-google.on-dark{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.26);color:#fff;backdrop-filter:blur(8px);box-shadow:none}
.btn-google.on-dark:hover{background:#fff;color:var(--ink);border-color:#fff}
.btn-lg{padding:19px 40px;font-size:1.06rem}

.btn-pair{display:inline-flex;align-items:center;gap:8px}
.arrow-circ{
  width:56px;height:56px;border-radius:50%;
  background:linear-gradient(135deg,#2d85ff 0%,var(--brand) 52%,#0345b0 100%);color:#fff;
  border:1px solid rgba(255,255,255,.18);
  box-shadow:0 10px 24px rgba(5,104,235,.3), inset 0 1px 0 rgba(255,255,255,.26);
  display:inline-flex;align-items:center;justify-content:center;transition:.34s var(--ease);flex-shrink:0;
  cursor:pointer;
}
.arrow-circ svg{width:19px;height:19px;transition:.34s var(--ease)}
.arrow-circ:hover{background:linear-gradient(135deg,#143a6e,var(--ink));box-shadow:0 14px 30px rgba(7,18,36,.3);transform:translateY(-2px)}
.arrow-circ:hover svg{transform:rotate(45deg)}
.btn-pair .btn-sm + .arrow-circ{width:44px;height:44px}
.arrow-circ.sm{width:42px;height:42px}
.arrow-circ.sm svg{width:15px;height:15px}
.arrow-circ.light{background:#fff;color:var(--ink)}
.arrow-circ.light:hover{background:var(--brand);color:#fff}

/* ==========================================================================
   SCROLL ANIMATIONS
   Elements are visible by default; the .js class (set by the inline script)
   hides them until they scroll into view, so the page still works without JS.
   ========================================================================== */
/* uses the independent translate/scale properties, so `transform` stays free
   for each component's own stagger and hover states */
.js [data-rv]{opacity:0;translate:0 34px;transition:opacity .9s var(--ease-out),translate .9s var(--ease-out),scale .9s var(--ease-out)}
.js [data-rv="left"]{translate:-40px 0}
.js [data-rv="right"]{translate:40px 0}
.js [data-rv="zoom"]{translate:none;scale:.94}
.js [data-rv="vehicle"]{translate:52% 0}
.js [data-rv="vehicle"].in{translate:none;transition:opacity .7s var(--ease-out),translate 1.25s var(--ease-out)}
.js [data-rv].in{opacity:1;translate:none;scale:none}
.js [data-rv][data-d="1"]{transition-delay:.1s}
.js [data-rv][data-d="2"]{transition-delay:.2s}
.js [data-rv][data-d="3"]{transition-delay:.3s}
.js [data-rv][data-d="4"]{transition-delay:.4s}
.js [data-rv][data-d="5"]{transition-delay:.5s}
@media (prefers-reduced-motion:reduce){
  .js [data-rv]{opacity:1 !important;translate:none !important;scale:none !important;transition:none}
  .js .cta-rig.in .cta-beam{animation:none;opacity:.55}
  .hero-bg{animation:none !important}
}

/* ==========================================================================
   ANNOUNCEMENT TICKER + HEADER
   ========================================================================== */
.ticker{
  background:var(--ink);color:#fff;position:relative;overflow:hidden;
  border-bottom:1px solid rgba(255,255,255,.07);
}
.ticker::before{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(100deg,rgba(5,104,235,0) 0%,rgba(5,104,235,.26) 38%,rgba(5,104,235,.5) 50%,rgba(5,104,235,.26) 62%,rgba(5,104,235,0) 100%);
  transform:translateX(-100%);animation:tickSweep 7s var(--ease-out) infinite;
}
@keyframes tickSweep{0%{transform:translateX(-100%)}55%,100%{transform:translateX(100%)}}
.ticker-in{
  position:relative;z-index:1;display:flex;align-items:center;gap:22px;
  min-height:48px;max-width:var(--maxw-wide);margin:0 auto;padding:0 var(--gut);
}
.ticker-live{
  display:inline-flex;align-items:center;gap:9px;flex-shrink:0;
  font-family:'Epilogue',Arial,sans-serif;font-weight:700;font-size:.78rem;
  letter-spacing:.14em;text-transform:uppercase;color:#fff;
  background:rgba(34,197,94,.13);border:1px solid rgba(34,197,94,.42);transition:.4s var(--ease);
  border-radius:var(--pill);padding:6px 16px;
}
.ticker-live{--sig:#22c55e}
.ticker-live i{
  width:8px;height:8px;border-radius:50%;background:var(--sig);position:relative;flex-shrink:0;
  box-shadow:0 0 10px var(--sig);
}
.ticker-live i::after{
  content:"";position:absolute;inset:0;border-radius:50%;background:var(--sig);
  animation:livePing 1.9s var(--ease-out) infinite;
}
.ticker-live.is-closed{--sig:#f0a33c;background:rgba(240,163,60,.13);border-color:rgba(240,163,60,.42)}
@keyframes livePing{0%{transform:scale(1);opacity:.75}70%,100%{transform:scale(3.4);opacity:0}}
.ticker-mq{
  flex:1;overflow:hidden;min-width:0;
  -webkit-mask:linear-gradient(90deg,transparent,#000 5%,#000 95%,transparent);
  mask:linear-gradient(90deg,transparent,#000 5%,#000 95%,transparent);
}
.ticker-track{display:flex;align-items:center;gap:0;width:max-content;animation:tickRoll 34s linear infinite}
.ticker:hover .ticker-track{animation-play-state:paused}
@keyframes tickRoll{to{transform:translateX(-50%)}}
.ticker-track span{
  font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:.88rem;
  letter-spacing:.03em;color:#ececed;white-space:nowrap;padding:0 4px;
}
.ticker-track span em{font-style:normal;color:var(--brand-l);font-weight:700}
.ticker-track b{
  color:var(--brand);font-size:.8rem;padding:0 18px;flex-shrink:0;line-height:1;
  display:inline-flex;align-items:center;
}
.ticker-track b svg{width:12px;height:12px;animation:spin 9s linear infinite}
@media (prefers-reduced-motion:reduce){
  .ticker-track,.ticker::before,.ticker-live i::after,.ticker-track b svg{animation:none}
}
@media(max-width:760px){
  .ticker-in{gap:14px;padding:0 14px}
  .ticker-live{font-size:.68rem;letter-spacing:.1em;padding:5px 12px}
  .ticker-track span{font-size:.8rem}
  .ticker-track b{padding:0 13px}
}

header{
  position:sticky;top:0;z-index:70;background:rgba(255,255,255,.98);
  border-bottom:1px solid var(--line-2);
  transition:box-shadow .3s var(--ease);
}
header.stuck{box-shadow:0 8px 30px rgba(7,18,36,.08)}
.hdr-in{display:flex;align-items:center;gap:20px;min-height:92px;transition:min-height .3s var(--ease)}
header.stuck .hdr-in{min-height:76px}
.brand{display:flex;align-items:center;flex-shrink:0}
.logo-img{width:min(246px,50vw);height:auto;transition:width .3s var(--ease)}
header.stuck .logo-img{width:min(212px,46vw)}
.nav{margin-left:auto;display:flex;align-items:center;gap:2px}
.nav a,.nav label{
  font-family:'Epilogue',Arial,sans-serif;font-weight:500;font-size:.97rem;color:var(--ink);
  padding:10px 13px;border-radius:var(--pill);transition:.2s;white-space:nowrap;position:relative;
}
.nav a::after,.nav label::after{
  content:"";position:absolute;left:13px;right:13px;bottom:4px;height:2px;background:var(--brand);
  transform:scaleX(0);transform-origin:left;transition:transform .3s var(--ease);border-radius:2px;
}
.nav a:hover,.nav label:hover{color:var(--brand)}
.nav a:hover,.nav label:hover::after{transform:scaleX(1)}
.hdr-cta{display:inline-flex;gap:10px;align-items:center;margin-left:12px;flex-shrink:0}
.menu-tog,.menu-chk{display:none}
@media(max-width:1500px){.hdr-cta .btn-line{display:none}}
@media(max-width:1280px){
  .nav a,.nav label{padding:10px 10px;font-size:.93rem}
  .hdr-cta .arrow-circ{display:none}
}
@media(max-width:1120px){
  .nav{
    position:fixed;inset:92px 0 auto 0;flex-direction:column;align-items:stretch;gap:0;background:#fff;
    border-bottom:1px solid var(--line);box-shadow:var(--sh);padding:10px var(--gut) 22px;
    clip-path:inset(0 0 100% 0);pointer-events:none;transition:clip-path .34s var(--ease);
    max-height:calc(100vh - 92px);overflow:auto;
  }
  .nav a,.nav label{padding:14px 4px;border-bottom:1px solid var(--line-2);font-size:1.05rem;border-radius:0}
  .nav a::after,.nav label::after{display:none}
  .hdr-cta{display:none}
  .menu-tog{
    display:inline-flex;margin-left:auto;align-items:center;justify-content:center;width:50px;height:50px;
    border:1px solid var(--line);border-radius:14px;cursor:pointer;background:#fff;
  }
  .menu-tog span,.menu-tog span::before,.menu-tog span::after{
    content:"";display:block;width:22px;height:2px;background:var(--ink);position:relative;transition:.24s;border-radius:2px;
  }
  .menu-tog span::before{position:absolute;top:-7px}
  .menu-tog span::after{position:absolute;top:7px}
  .menu-chk:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto}
  .menu-chk:checked ~ .menu-tog span{background:transparent}
  .menu-chk:checked ~ .menu-tog span::before{top:0;transform:rotate(45deg)}
  .menu-chk:checked ~ .menu-tog span::after{top:0;transform:rotate(-45deg)}
  .nav .m-cta{display:inline-flex;margin-top:16px;border:0;justify-content:center}
}
@media(min-width:1121px){.nav .m-cta{display:none}}

/* ==========================================================================
   HERO
   ========================================================================== */
.hero-outer{padding:14px var(--gut) 0;max-width:var(--maxw-wide);margin:0 auto}
.hero{
  position:relative;border-radius:var(--r-xl);overflow:hidden;background:var(--ink);
  isolation:isolate;min-height:clamp(600px,88vh,880px);display:flex;align-items:center;
}
.hero-bg{
  position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0;
  animation:kb 26s ease-in-out infinite alternate;
}
@keyframes kb{from{transform:scale(1.02)}to{transform:scale(1.12)}}
.hero::after{
  content:"";position:absolute;inset:0;z-index:1;
  background:
    radial-gradient(62% 46% at 50% 40%, rgba(6,18,38,.72) 0%, rgba(6,18,38,.30) 58%, rgba(6,18,38,0) 82%),
    radial-gradient(120% 86% at 50% 118%, rgba(5,104,235,.32) 0%, rgba(5,104,235,0) 56%),
    linear-gradient(180deg, rgba(6,18,38,.74) 0%, rgba(6,18,38,.42) 40%, rgba(6,18,38,.88) 100%);
}
.hero-in{
  position:relative;z-index:3;width:100%;text-align:center;
  padding:clamp(70px,8vw,120px) clamp(22px,5vw,80px) clamp(130px,14vw,200px);
}
.hero h1{color:#fff;max-width:19ch;margin:0 auto .42em}
.hero h1 .hl{color:var(--brand-l)}
.hero .sub{
  color:rgba(255,255,255,.84);font-size:clamp(1.04rem,1.25vw,1.24rem);
  max-width:62ch;margin:0 auto 36px;
}
.hero-cta{display:flex;gap:14px;justify-content:center;align-items:center;flex-wrap:wrap}

/* hero quick stats row */
.hero-stats{
  display:flex;justify-content:center;gap:clamp(18px,3vw,56px);flex-wrap:wrap;
  margin-top:clamp(36px,4vw,56px);padding-top:clamp(26px,3vw,38px);
  border-top:1px solid rgba(255,255,255,.17);max-width:900px;margin-left:auto;margin-right:auto;
}
.hstat{color:#fff;text-align:center;min-width:120px}
.hstat b{display:block;font-family:'Epilogue',Arial,sans-serif;font-size:clamp(1.6rem,2.4vw,2.3rem);line-height:1}
.hstat span{display:block;font-size:.9rem;color:rgba(255,255,255,.66);margin-top:6px}

/* scroll cue */
.scroll-cue{
  position:absolute;left:50%;bottom:clamp(18px,2.4vw,30px);transform:translateX(-50%);z-index:4;
  display:flex;flex-direction:column;align-items:center;gap:8px;color:rgba(255,255,255,.6);
  font-size:.74rem;letter-spacing:.2em;text-transform:uppercase;font-family:'Epilogue',Arial,sans-serif;
}
.scroll-cue i{
  width:1px;height:38px;background:linear-gradient(180deg,rgba(255,255,255,.08),rgba(255,255,255,.75));
  position:relative;overflow:hidden;
}
.scroll-cue i::after{
  content:"";position:absolute;left:0;top:-38px;width:1px;height:38px;background:var(--brand);
  animation:cue 2.2s var(--ease) infinite;
}
@keyframes cue{0%{top:-38px}60%,100%{top:38px}}
@media(max-width:900px){.scroll-cue{display:none}}

/* ---------- Booking bar ---------- */
.bookbar-outer{
  max-width:calc(var(--maxw-wide) - 120px);margin:0 auto;padding:0 var(--gut);
  position:relative;z-index:20;margin-top:clamp(-100px,-9vw,-72px);
}
.bookbar{
  background:#fff;border-radius:var(--r-lg);box-shadow:var(--sh-lg);
  padding:clamp(18px,1.9vw,28px);display:grid;
  grid-template-columns:repeat(4,1fr) auto;gap:clamp(12px,1.4vw,20px);align-items:end;
}
.bb-field{display:flex;flex-direction:column;gap:7px;min-width:0}
.bb-field label{
  font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:.84rem;color:var(--ink);
  display:flex;align-items:center;gap:7px;
}
.bb-field label svg{width:15px;height:15px;color:var(--brand)}
.bb-field select,.bb-field input{
  font-family:'DM Sans',Arial,sans-serif;font-size:.97rem;color:var(--ink-2);padding:14px 16px;
  border:1.5px solid var(--line);border-radius:var(--r-sm);background:var(--soft);width:100%;
  transition:.22s;appearance:none;
}
.bb-field select{
  background-image:url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%235e6a7d' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='m6 9 6 6 6-6'/%3E%3C/svg%3E");
  background-repeat:no-repeat;background-position:right 14px center;background-size:16px;padding-right:40px;
}
.bb-field select:focus,.bb-field input:focus{outline:none;border-color:var(--brand);background:#fff}
.bb-go{height:52px;align-self:end}
@media(max-width:1080px){.bookbar{grid-template-columns:1fr 1fr}.bb-go{grid-column:1/-1;width:100%}}
@media(max-width:560px){.bookbar{grid-template-columns:1fr}.bookbar-outer{margin-top:-56px}}

/* ==========================================================================
   TRUST BAND
   ========================================================================== */
.trust{
  position:relative;border-radius:var(--r-xl);overflow:hidden;background:var(--ink);
  isolation:isolate;padding:clamp(24px,2.2vw,38px) clamp(18px,2.4vw,46px);
}
.trust::before{
  content:"";position:absolute;inset:0;z-index:0;
  background:
    radial-gradient(62% 120% at 8% 0%, rgba(5,104,235,.26) 0%, rgba(5,104,235,0) 60%),
    radial-gradient(54% 120% at 96% 100%, rgba(5,104,235,.18) 0%, rgba(5,104,235,0) 62%);
}
.trust-grid{position:relative;z-index:1;display:grid;grid-template-columns:repeat(4,1fr)}
.tcell{
  position:relative;padding:clamp(18px,1.8vw,30px) clamp(16px,1.8vw,34px);
  display:flex;align-items:flex-start;gap:18px;transition:.42s var(--ease);border-radius:var(--r-md);
}
.tcell + .tcell::before{
  content:"";position:absolute;left:0;top:14%;bottom:14%;width:1px;
  background:linear-gradient(180deg,rgba(255,255,255,0),rgba(255,255,255,.18),rgba(255,255,255,0));
}
.tcell:hover{background:rgba(255,255,255,.05);transform:translateY(-4px)}
.tcell-ico{
  --ic:#fff;--ic-a:#cfe2ff;--ic-bg:#0450c4;
  width:58px;height:58px;border-radius:16px;flex-shrink:0;padding:9px;
  background:linear-gradient(135deg,#2d85ff,var(--brand));border:1px solid rgba(255,255,255,.2);
  box-shadow:0 8px 20px rgba(5,104,235,.34), inset 0 1px 0 rgba(255,255,255,.3);
  display:flex;align-items:center;justify-content:center;transition:.42s var(--ease);
}
.tcell:hover .tcell-ico{--ic:var(--ink);--ic-a:var(--brand);--ic-bg:#fff;background:#fff;border-color:#fff;transform:rotate(-6deg);box-shadow:0 10px 24px rgba(0,0,0,.3)}
.tcell-txt{min-width:0}
.tcell b{
  display:block;font-family:'Epilogue',Arial,sans-serif;font-weight:700;
  font-size:clamp(1.85rem,2.5vw,2.6rem);line-height:1;color:#fff;letter-spacing:-.035em;
}
.tcell span{display:block;font-size:.95rem;color:rgba(255,255,255,.6);margin-top:8px;line-height:1.4}
@media(max-width:1000px){
  .trust-grid{grid-template-columns:1fr 1fr}
  .tcell:nth-child(3)::before,.tcell:nth-child(2)+.tcell::before{content:none}
  .tcell:nth-child(2)::before,.tcell:nth-child(4)::before{content:""}
}
@media(max-width:580px){
  .trust-grid{grid-template-columns:1fr}
  .tcell + .tcell::before{left:8%;right:8%;top:0;bottom:auto;width:auto;height:1px;
    background:linear-gradient(90deg,rgba(255,255,255,0),rgba(255,255,255,.18),rgba(255,255,255,0))}
}

/* ==========================================================================
   ABOUT
   ========================================================================== */
.about-grid{display:grid;grid-template-columns:1.04fr 1fr;gap:clamp(36px,5vw,90px);align-items:center}
.about-media{position:relative;min-height:clamp(420px,42vw,620px)}
.blob-a{
  position:absolute;left:0;top:0;width:68%;aspect-ratio:1/1;overflow:hidden;
  border-radius:50%;border:1px solid var(--line);
}
.blob-b{
  position:absolute;right:0;bottom:0;width:56%;aspect-ratio:1/1;overflow:hidden;
  border-radius:50%;border:7px solid #fff;box-shadow:var(--sh);
}
.blob-a img,.blob-b img{width:100%;height:100%;object-fit:cover;transition:transform .9s var(--ease)}
.about-media:hover .blob-a img,.about-media:hover .blob-b img{transform:scale(1.05)}
.about-media .deco-ast{position:absolute;left:60%;top:14%;width:62px;height:auto;z-index:3;color:var(--brand);animation:spin 18s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.spark{position:absolute;left:12%;bottom:5%;width:34px;height:34px;color:var(--ink);z-index:3}
.abt-list{margin:28px 0 32px;padding:0;list-style:none;display:grid;gap:4px}
.abt-list li{display:flex;gap:18px;padding:22px 0;border-bottom:1px solid var(--line-2)}
.abt-list li:last-child{border-bottom:0}
.abt-ico{
  width:64px;height:64px;border-radius:50%;background:var(--brand-soft);padding:12px;
  display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:.34s var(--ease);
}
.abt-list li:hover .abt-ico{--ic:#fff;--ic-a:#fff;--ic-bg:var(--brand);background:var(--brand)}
.abt-list h3{margin:0 0 4px}
.abt-list p{margin:0;color:var(--muted);font-size:.99rem}

/* ==========================================================================
   SERVICES PANEL
   ========================================================================== */
.panel{
  background:var(--cream);border-radius:var(--r-xl);
  padding:clamp(44px,5vw,96px) clamp(22px,3.4vw,70px);position:relative;overflow:hidden;
}
.panel-wrap{max-width:var(--maxw-wide);margin:0 auto;padding:0 var(--gut)}
.svc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(16px,1.8vw,26px);margin-top:clamp(36px,4vw,58px)}
.svc{
  background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);
  padding:clamp(26px,2.4vw,36px);transition:.4s var(--ease);display:flex;flex-direction:column;
  position:relative;overflow:hidden;
}
.svc::before{
  content:"";position:absolute;left:0;right:0;top:0;height:4px;background:var(--brand);
  transform:scaleX(0);transform-origin:left;transition:transform .55s var(--ease-out);
}
.svc:hover::before{transform:scaleX(1)}
.svc-num{
  position:absolute;right:16px;top:2px;z-index:0;pointer-events:none;
  font-family:'Epilogue',Arial,sans-serif;font-weight:800;font-size:4.6rem;line-height:1;
  color:rgba(7,18,36,.045);letter-spacing:-.04em;transition:.44s var(--ease);
}
.svc:hover .svc-num{color:rgba(5,104,235,.1);transform:translateY(-4px)}
.svc h3,.svc p,.svc .arrow-circ{position:relative;z-index:1}
.svc:nth-child(2){transform:translateY(16px)}
.svc:nth-child(3){transform:translateY(32px)}
.svc:nth-child(4){transform:translateY(48px)}
.svc:hover{box-shadow:var(--sh-lg);border-color:#fff}
.svc:nth-child(1):hover{transform:translateY(-10px)}
.svc:nth-child(2):hover{transform:translateY(6px)}
.svc:nth-child(3):hover{transform:translateY(22px)}
.svc:nth-child(4):hover{transform:translateY(38px)}
.svc-ico{
  width:86px;height:86px;border-radius:50%;background:var(--brand-soft);
  display:flex;align-items:center;justify-content:center;margin-bottom:24px;
  transition:.44s var(--ease);padding:15px;position:relative;z-index:1;
}
.svc:hover .svc-ico{--ic:#fff;--ic-a:#fff;--ic-bg:var(--brand);background:var(--brand);transform:scale(1.05)}
.svc h3{margin-bottom:10px}
.svc p{color:var(--muted);font-size:.98rem;margin-bottom:24px}
.svc .arrow-circ{margin-top:auto;align-self:flex-start}
.panel-foot{margin-top:clamp(62px,6vw,92px);text-align:center;color:var(--muted);max-width:66ch;margin-left:auto;margin-right:auto}
@media(max-width:1180px){
  .svc-grid{grid-template-columns:1fr 1fr}
  .svc,.svc:nth-child(2),.svc:nth-child(3),.svc:nth-child(4){transform:none}
  .svc:hover,.svc:nth-child(2):hover,.svc:nth-child(3):hover,.svc:nth-child(4):hover{transform:translateY(-8px)}
  .panel-foot{margin-top:36px}
}
@media(max-width:640px){.svc-grid{grid-template-columns:1fr}}

/* ==========================================================================
   RENTAL FLEET (tabs)
   ========================================================================== */
.fleet-tabs{position:relative;z-index:3;display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:clamp(32px,3.4vw,48px) 0 clamp(28px,3.2vw,46px)}
.fleet-tabs label{
  font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:.99rem;padding:15px 30px;
  border-radius:var(--pill);background:#fff;border:1.5px solid var(--line);color:var(--ink);
  cursor:pointer;transition:.3s var(--ease);white-space:nowrap;
}
.fleet-tabs label:hover{border-color:var(--brand);color:var(--brand);transform:translateY(-2px)}
.fleet-panes{position:relative;z-index:1}
.fleet-pane{display:none}
.fleet-r{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
#fl1:checked ~ .fleet-tabs label[for="fl1"],
#fl2:checked ~ .fleet-tabs label[for="fl2"],
#fl3:checked ~ .fleet-tabs label[for="fl3"],
#fl4:checked ~ .fleet-tabs label[for="fl4"],
#fl5:checked ~ .fleet-tabs label[for="fl5"]{
  background:var(--brand);border-color:var(--brand);color:#fff;box-shadow:0 12px 28px rgba(5,104,235,.32);
}
#fl1:checked ~ .fleet-panes #pane1,
#fl2:checked ~ .fleet-panes #pane2,
#fl3:checked ~ .fleet-panes #pane3,
#fl4:checked ~ .fleet-panes #pane4,
#fl5:checked ~ .fleet-panes #pane5{display:block}
#fl1:checked ~ .fleet-panes #pane1 .fleet-img img,
#fl2:checked ~ .fleet-panes #pane2 .fleet-img img,
#fl3:checked ~ .fleet-panes #pane3 .fleet-img img,
#fl4:checked ~ .fleet-panes #pane4 .fleet-img img,
#fl5:checked ~ .fleet-panes #pane5 .fleet-img img{animation:carIn .75s var(--ease-out) both}
#fl1:checked ~ .fleet-panes #pane1 .fleet-info,
#fl2:checked ~ .fleet-panes #pane2 .fleet-info,
#fl3:checked ~ .fleet-panes #pane3 .fleet-info,
#fl4:checked ~ .fleet-panes #pane4 .fleet-info,
#fl5:checked ~ .fleet-panes #pane5 .fleet-info{animation:rvIn .7s var(--ease-out) both .08s}
@keyframes carIn{from{opacity:0;transform:translateX(-44px) scale(.96)}to{opacity:1;transform:none}}
@keyframes rvIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}

.fleet-split{display:grid;grid-template-columns:1.16fr .84fr;gap:clamp(28px,4vw,76px);align-items:start;min-height:clamp(300px,26vw,440px)}
.fleet-img{
  position:relative;display:flex;align-items:center;justify-content:center;
  padding:0;height:clamp(300px,26vw,440px);
}
.fleet-img::before{
  content:"";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  width:74%;aspect-ratio:1/1;border-radius:50%;
  background:radial-gradient(circle at 50% 50%, var(--brand-soft-2) 0%, var(--brand-soft) 52%, rgba(255,241,234,0) 73%);
  z-index:0;
}
.fleet-img img{
  position:relative;z-index:1;width:100%;max-width:780px;height:100%;object-fit:contain;
  filter:drop-shadow(0 18px 26px rgba(7,18,36,.18));
}
.fleet-price{display:flex;align-items:baseline;gap:4px;font-family:'Epilogue',Arial,sans-serif}
.fleet-price .cur{font-size:clamp(1.5rem,2vw,2rem);font-weight:700;color:var(--ink)}
.fleet-price .amt{font-size:clamp(2.8rem,4.6vw,4.2rem);font-weight:700;color:var(--ink);line-height:1;letter-spacing:-.035em}
.fleet-price.poa .amt{font-size:clamp(1.8rem,2.8vw,2.5rem)}
.fleet-per{color:var(--muted);font-size:.99rem;margin:8px 0 0}
.fleet-rule{height:1px;background:var(--line);margin:26px 0}
.fleet-specs{list-style:none;margin:0 0 30px;padding:0;display:grid;gap:15px}
.fleet-specs li{display:flex;align-items:center;gap:13px;color:var(--ink-2);font-size:1.01rem}
.fleet-specs li svg{width:20px;height:20px;color:var(--muted-2)}
.fleet-specs li span{color:var(--muted)}
.fleet-specs li b{font-weight:600;color:var(--ink)}
.fleet-act{display:flex;align-items:center;gap:24px;flex-wrap:wrap}
.fleet-call{display:inline-flex;align-items:center;gap:9px;font-family:'Epilogue',Arial,sans-serif;font-weight:600;color:var(--ink);font-size:1.04rem}
.fleet-call svg{width:17px;height:17px;color:var(--brand)}
.fleet-call:hover{color:var(--brand)}
.fleet-name{font-size:clamp(1.4rem,2.1vw,1.8rem);margin-bottom:6px}
.fleet-tagline{color:var(--muted);font-size:1rem;margin-bottom:24px}
@media(max-width:1000px){
  .fleet-split{grid-template-columns:1fr;gap:24px}
  .fleet-img{order:-1}
  /* every model stays visible: a wrapped grid instead of a side scroller */
  .fleet-tabs{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;overflow:visible}
  .fleet-tabs label{padding:14px 10px;font-size:.95rem;text-align:center}
  .fleet-tabs label:nth-child(5){grid-column:1/-1}
}

/* ==========================================================================
   CATEGORY CARDS
   ========================================================================== */
.cats{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(16px,1.8vw,26px)}
.cat{
  position:relative;width:100%;min-width:0;border-radius:var(--r-lg);overflow:hidden;aspect-ratio:4/3;min-height:300px;
  display:flex;align-items:flex-end;transition:.45s var(--ease);
}
.cat:hover{transform:translateY(-10px);box-shadow:var(--sh-lg)}
.cat img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 46%;transition:transform .9s var(--ease)}
.cat:hover img{transform:scale(1.08)}
.cat::after{
  content:"";position:absolute;inset:0;
  background:linear-gradient(180deg,rgba(6,18,38,.5) 0%,rgba(6,18,38,.04) 40%,rgba(6,18,38,.88) 100%);
  transition:.45s var(--ease);
}
.cat:hover::after{background:linear-gradient(180deg,rgba(6,18,38,.46) 0%,rgba(5,104,235,.14) 44%,rgba(6,18,38,.92) 100%)}
.cat-in{position:relative;z-index:2;padding:clamp(24px,2.4vw,34px);width:100%;display:flex;align-items:flex-end;justify-content:space-between;gap:16px}
.cat-in h3{color:#fff;margin:0 0 6px;font-size:clamp(1.25rem,1.8vw,1.6rem)}
.cat-in p{color:rgba(255,255,255,.8);margin:0;font-size:.96rem}
.cat-top{position:absolute;z-index:2;top:clamp(24px,2.4vw,34px);left:clamp(24px,2.4vw,34px)}
.cat-pill{
  display:inline-flex;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.28);
  backdrop-filter:blur(10px);color:#fff;border-radius:var(--pill);padding:8px 18px;
  font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:.85rem;
}
@media(max-width:1000px){.cats{grid-template-columns:1fr 1fr}}
@media(max-width:640px){.cats{grid-template-columns:1fr}}

/* ==========================================================================
   PROCESS
   ========================================================================== */
.proc-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(36px,5vw,90px);align-items:center}
.proc-list{margin-top:32px}
.proc{border-bottom:1px solid var(--line)}
.proc summary{
  list-style:none;cursor:pointer;display:flex;align-items:center;gap:18px;padding:24px 0;
  font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:clamp(1.08rem,1.5vw,1.32rem);
  color:var(--ink);transition:.25s;
}
.proc summary::-webkit-details-marker{display:none}
.proc summary .pn{
  width:38px;height:38px;border-radius:50%;background:var(--brand-soft);color:var(--brand);
  display:inline-flex;align-items:center;justify-content:center;font-size:.95rem;flex-shrink:0;transition:.3s var(--ease);
}
.proc[open] summary{color:var(--brand)}
.proc[open] summary .pn{background:var(--brand);color:#fff}
.proc summary .pchev{margin-left:auto;width:22px;height:22px;color:var(--ink);transition:.3s var(--ease);flex-shrink:0}
.proc[open] summary .pchev{transform:rotate(180deg);color:var(--brand)}
.proc-body{padding:0 0 26px 56px;color:var(--muted);font-size:1rem}
.proc-body p{margin:0}

.proc-media{position:relative;min-height:clamp(420px,44vw,620px)}
.proc-shape{position:absolute;inset:0 12% 8% 0;overflow:hidden;border-radius:300px 300px 26px 26px;border:1px solid var(--line)}
.proc-shape img{width:100%;height:100%;object-fit:cover;transition:transform 1s var(--ease)}
.proc-media:hover .proc-shape img{transform:scale(1.06)}
.proc-stat{
  position:absolute;right:0;bottom:11%;z-index:3;background:var(--brand);color:#fff;
  border-radius:var(--r-md);padding:26px 28px;max-width:268px;box-shadow:var(--sh-lg);
}
.proc-stat b{display:block;font-family:'Epilogue',Arial,sans-serif;font-size:2.2rem;line-height:1}
.proc-stat span{display:block;font-size:.99rem;line-height:1.45;margin-top:8px;color:rgba(255,255,255,.93)}
.proc-stat hr{border:0;border-top:1px solid rgba(255,255,255,.34);margin:18px 0 0}
.proc-media .spark{left:auto;right:28%;bottom:1%}
@media(max-width:1000px){
  .proc-grid{grid-template-columns:1fr}
  .proc-media{order:-1;min-height:380px}
  .proc-shape{inset:0 0 12% 0;border-radius:220px 220px 20px 20px}
  .proc-stat{right:4%;max-width:230px;padding:20px 22px}
}

/* ==========================================================================
   WHY CHOOSE - dark panel with glass cards
   ========================================================================== */
.why{
  position:relative;border-radius:var(--r-xl);overflow:hidden;background:var(--ink);isolation:isolate;
  padding:clamp(44px,5vw,96px) clamp(24px,3.4vw,76px);
}
.why::before{
  content:"";position:absolute;inset:0;z-index:0;
  background:
    radial-gradient(70% 90% at 12% 8%, rgba(5,104,235,.22) 0%, rgba(5,104,235,0) 55%),
    radial-gradient(60% 80% at 92% 95%, rgba(5,104,235,.16) 0%, rgba(5,104,235,0) 58%);
}
.why-grid{position:relative;z-index:2;display:grid;grid-template-columns:.86fr 1.14fr;gap:clamp(34px,4.4vw,80px);align-items:center}
.why h2{color:#fff}
.why .lead{color:rgba(255,255,255,.72)}
.why-media{position:relative;margin-top:34px;border-radius:var(--r-lg);overflow:hidden}
.why-media img{width:100%;height:auto;display:block}
.why-cards{display:grid;grid-template-columns:1fr 1fr;gap:clamp(14px,1.5vw,22px)}
.wcard{
  background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.12);border-radius:var(--r-lg);
  padding:clamp(24px,2.3vw,34px);position:relative;overflow:hidden;transition:.44s var(--ease);
  backdrop-filter:blur(6px);
}
.wcard::before{
  content:"";position:absolute;inset:0;background:var(--brand);transform:translateY(101%);
  transition:transform .5s var(--ease-out);z-index:0;
}
.wcard:hover::before{transform:translateY(0)}
.wcard:hover{transform:translateY(-8px);border-color:var(--brand)}
.wcard > *{position:relative;z-index:1}
.wcard-n{
  font-family:'Epilogue',Arial,sans-serif;font-weight:700;font-size:.82rem;letter-spacing:.14em;
  color:var(--brand-l);margin-bottom:18px;display:block;transition:.44s var(--ease);
}
.wcard:hover .wcard-n{color:rgba(255,255,255,.8)}
.wcard-ico{
  --ic:#fff;--ic-a:var(--brand-l);--ic-bg:#0f2444;
  width:64px;height:64px;border-radius:17px;background:rgba(255,255,255,.08);
  border:1px solid rgba(255,255,255,.12);padding:11px;
  display:flex;align-items:center;justify-content:center;margin-bottom:20px;transition:.44s var(--ease);
}
.wcard:hover .wcard-ico{--ic:#fff;--ic-a:#fff;--ic-bg:var(--brand);background:rgba(255,255,255,.2);border-color:transparent}
.wcard h3{color:#fff;margin:0 0 9px;font-size:1.16rem}
.wcard p{color:rgba(255,255,255,.66);margin:0;font-size:.97rem;transition:.44s var(--ease)}
.wcard:hover p{color:rgba(255,255,255,.92)}
@media(max-width:1100px){.why-grid{grid-template-columns:1fr}}
@media(max-width:560px){.why-cards{grid-template-columns:1fr}}

/* ==========================================================================
   FAQ
   ========================================================================== */
.faq-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(36px,5vw,86px);align-items:center}
.faq-media{position:relative}
.faq-card{
  position:absolute;right:clamp(-16px,-1.4vw,-8px);bottom:clamp(-26px,-2vw,-16px);z-index:3;
  background:var(--ink);color:#fff;border-radius:var(--r-lg);padding:clamp(22px,2vw,28px);
  max-width:300px;box-shadow:var(--sh-lg);
}
.faq-card b{display:block;font-family:'Epilogue',Arial,sans-serif;font-size:1.1rem;color:#fff;margin-bottom:6px}
.faq-card p{margin:0 0 16px;font-size:.93rem;color:rgba(255,255,255,.68);line-height:1.5}
.faq-card .fc-phone{
  display:inline-flex;align-items:center;gap:10px;font-family:'Epilogue',Arial,sans-serif;
  font-weight:700;font-size:1.18rem;color:#fff;letter-spacing:-.01em;
}
.faq-card .fc-phone svg{width:17px;height:17px;color:var(--brand-l)}
.faq-card .fc-phone:hover{color:var(--brand-l)}
@media(max-width:1000px){.faq-card{position:static;max-width:none;margin-top:18px}}
.faq-media img{border-radius:var(--r-lg);width:100%;height:auto;object-fit:cover}
.faq-media .deco-ast{position:absolute;right:-14px;top:-22px;width:58px;height:auto;color:var(--brand);animation:spin 20s linear infinite}
.faq-list{margin-top:28px}
.faq{
  border:1px solid rgba(7,18,36,.08);border-radius:var(--r-md);background:rgba(255,255,255,.55);
  margin-bottom:12px;transition:.36s var(--ease);overflow:hidden;position:relative;
}
.faq::before{
  content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--brand);
  transform:scaleY(0);transform-origin:top;transition:transform .36s var(--ease);
}
.faq:hover{background:#fff;border-color:rgba(7,18,36,.14);box-shadow:0 8px 22px rgba(7,18,36,.05)}
.faq[open]{background:#fff;border-color:rgba(5,104,235,.3);box-shadow:0 14px 34px rgba(7,18,36,.08)}
.faq[open]::before{transform:scaleY(1)}
.faq-n{
  width:32px;height:32px;border-radius:50%;flex-shrink:0;background:var(--brand-soft);color:var(--brand);
  display:inline-flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:700;
  transition:.36s var(--ease);
}
.faq[open] .faq-n{background:var(--brand);color:#fff}
.faq summary{
  list-style:none;cursor:pointer;display:flex;align-items:center;gap:16px;
  padding:20px clamp(18px,1.8vw,26px);
  font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:clamp(1.02rem,1.4vw,1.2rem);
  color:var(--ink);transition:.25s;
}
.faq summary::-webkit-details-marker{display:none}
.faq summary .pchev{margin-left:auto;width:22px;height:22px;transition:.3s var(--ease);flex-shrink:0}
.faq[open] summary{color:var(--brand)}
.faq[open] summary .pchev{transform:rotate(180deg)}
.faq-body{padding:0 clamp(18px,1.8vw,26px) 24px 64px;color:var(--muted);font-size:1rem;max-width:72ch}
.faq-body p{margin:0}
@media(max-width:1000px){.faq-grid{grid-template-columns:1fr}}

/* ==========================================================================
   TESTIMONIALS
   ========================================================================== */
.testi-top{display:grid;grid-template-columns:1.1fr .9fr;gap:clamp(30px,4vw,70px);align-items:end;margin-bottom:clamp(36px,4vw,58px)}
.rating-card{
  background:var(--ink);color:#fff;border-radius:var(--r-lg);padding:clamp(26px,2.4vw,36px);
  display:flex;align-items:center;gap:clamp(20px,2.4vw,34px);position:relative;overflow:hidden;
}
.rating-card::before{
  content:"";position:absolute;right:-40px;top:-40px;width:200px;height:200px;border-radius:50%;
  background:radial-gradient(circle,rgba(5,104,235,.3) 0%,rgba(5,104,235,0) 70%);
}
.rating-big{font-family:'Epilogue',Arial,sans-serif;font-size:clamp(3rem,4.4vw,4.2rem);line-height:.9;letter-spacing:-.04em}
.rating-meta{position:relative;z-index:1}
.rating-meta .stars{margin-bottom:8px}
.rating-meta .stars svg{color:var(--brand-l)}
.rating-meta p{margin:0;color:rgba(255,255,255,.72);font-size:.96rem}

.testi-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(16px,1.8vw,26px)}
.testi{
  background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);
  padding:clamp(28px,2.6vw,40px);transition:.44s var(--ease);display:flex;flex-direction:column;
  position:relative;overflow:hidden;
}
.testi::before{
  content:"";position:absolute;inset:0;background:var(--ink);transform:translateY(101%);
  transition:transform .55s var(--ease-out);
}
.testi > *{position:relative;z-index:1}
.testi:hover::before{transform:translateY(0)}
.testi:hover{transform:translateY(-10px);border-color:var(--ink);box-shadow:var(--sh-lg)}
.testi:hover blockquote{color:#fff}
.testi:hover .testi-by{border-top-color:rgba(255,255,255,.18)}
.testi:hover .testi-by div b{color:#fff}
.testi:hover .testi-by div span{color:rgba(255,255,255,.66)}
.testi:hover .tquote{color:rgba(255,255,255,.1)}
.tquote{
  position:absolute;right:clamp(18px,2vw,26px);top:clamp(10px,1.4vw,18px);z-index:0;
  width:clamp(64px,6vw,92px);height:auto;color:var(--brand-soft);transition:.44s var(--ease);
}
.stars{display:flex;gap:4px;margin-bottom:20px}
.stars svg{width:19px;height:19px;color:var(--brand)}
.testi blockquote{margin:0 0 24px;color:var(--ink-2);font-size:1.03rem;line-height:1.68;transition:.44s var(--ease)}
.testi-by{display:flex;align-items:center;gap:14px;margin-top:auto;padding-top:22px;border-top:1px solid var(--line-2);transition:.44s var(--ease)}
.testi-av{
  width:50px;height:50px;border-radius:50%;background:var(--brand);color:#fff;
  display:flex;align-items:center;justify-content:center;flex-shrink:0;
  font-family:'Epilogue',Arial,sans-serif;font-weight:700;font-size:1rem;letter-spacing:.02em;line-height:1;
}
.testi-by div b{display:block;font-family:'Epilogue',Arial,sans-serif;font-size:1.04rem;color:var(--ink);transition:.44s var(--ease)}
.testi-by div span{display:block;font-size:.9rem;color:var(--muted);transition:.44s var(--ease)}
@media(max-width:1000px){.testi-grid{grid-template-columns:1fr}.testi-top{grid-template-columns:1fr}}

/* marquee of short review lines */
.marquee{overflow:hidden;margin-top:clamp(34px,3.6vw,54px);-webkit-mask:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent);mask:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent)}
.marquee-track{display:flex;gap:16px;width:max-content;animation:mq 42s linear infinite}
.marquee:hover .marquee-track{animation-play-state:paused}
@keyframes mq{to{transform:translateX(-50%)}}
.mq-item{
  display:inline-flex;align-items:center;gap:11px;background:var(--cream);border:1px solid var(--line);
  border-radius:var(--pill);padding:13px 26px;font-family:'Epilogue',Arial,sans-serif;font-weight:600;
  font-size:.95rem;color:var(--ink);white-space:nowrap;
}
.mq-item svg{width:16px;height:16px;color:var(--brand)}
@media (prefers-reduced-motion:reduce){.marquee-track{animation:none}}

/* ==========================================================================
   SERVICE AREAS
   ========================================================================== */
.areas{display:flex;flex-wrap:wrap;gap:10px;margin-top:28px}
.areas span{
  background:#fff;border:1px solid var(--line);border-radius:var(--pill);padding:11px 22px;
  font-size:.95rem;color:var(--ink-2);transition:.28s var(--ease);
}
.areas span:hover{background:var(--brand);border-color:var(--brand);color:#fff;transform:translateY(-3px)}
.areas-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(30px,4vw,70px);align-items:center}
@media(max-width:1000px){.areas-grid{grid-template-columns:1fr}}

/* about had no stacking rule, so the media column collapsed to ~130px */
@media(max-width:1000px){
  .about-grid{grid-template-columns:1fr;gap:clamp(28px,5vw,48px)}
  .about-media{
    width:100%;max-width:520px;margin:0 auto;
    min-height:min(78vw,430px);
  }
  .about-media .deco-ast{width:48px;left:58%;top:10%}
  .about-media .spark{width:26px;height:26px;left:6%;bottom:2%}
  .abt-list li{gap:14px;padding:20px 0}
  .abt-ico{width:56px;height:56px;padding:10px}
}

/* ==========================================================================
   CTA BAND
   ========================================================================== */
.cta-outer{
  max-width:var(--maxw-wide);margin:0 auto;position:relative;
  padding:clamp(70px,8vw,130px) var(--gut) clamp(62px,7vw,110px);
}
.ctaband{
  position:relative;border-radius:var(--r-xl);overflow:hidden;background:var(--ink);isolation:isolate;
  padding:clamp(38px,4vw,62px) clamp(26px,3.6vw,76px);
}
.ctaband .cta-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.42;z-index:0}
.ctaband::after{
  content:"";position:absolute;inset:0;z-index:1;
  background:
    radial-gradient(52% 120% at 86% 100%, rgba(5,104,235,.5) 0%, rgba(5,104,235,0) 62%),
    linear-gradient(100deg, rgba(6,18,38,.95) 0%, rgba(6,18,38,.72) 46%, rgba(6,18,38,.34) 100%);
}
.cta-in{position:relative;z-index:2;max-width:min(52%,690px)}
.ctaband h2{color:#fff;margin:0 0 16px;max-width:15ch}
.ctaband p{color:rgba(255,255,255,.76);max-width:50ch;margin:0 0 22px}
.cta-phone{
  display:inline-flex;align-items:center;gap:14px;font-family:'Epilogue',Arial,sans-serif;
  color:#fff;font-size:clamp(1.4rem,2.1vw,2rem);font-weight:700;letter-spacing:-.02em;margin-bottom:16px;
}
.cta-phone .cp-ico{
  width:56px;height:56px;border-radius:50%;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);
  display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:.3s var(--ease);
}
.cta-phone .cp-ico svg{width:22px;height:22px;color:var(--brand-l)}
.cta-phone:hover .cp-ico{background:var(--brand);border-color:var(--brand)}
.cta-phone:hover .cp-ico svg{color:#fff}
.cta-note{color:rgba(255,255,255,.56);font-size:.93rem;margin:0 0 24px}
.cta-btns{display:flex;gap:14px;flex-wrap:wrap;align-items:center}

/* branded van: drives in from the right, then the headlights blink */
.cta-rig{
  position:absolute;z-index:4;pointer-events:none;
  right:var(--gut);
  bottom:clamp(62px,7vw,110px);
  width:clamp(420px,46vw,880px);
}
.cta-vehicle{width:100%;height:auto;display:block;filter:drop-shadow(0 24px 44px rgba(7,18,36,.55))}

/* headlight cluster sits at ~15% / 47% of the artwork */
.cta-beam{
  position:absolute;left:7.5%;top:47.5%;width:15%;aspect-ratio:1.6/1;
  border-radius:50%;opacity:0;mix-blend-mode:screen;pointer-events:none;
  background:radial-gradient(ellipse at center,
    rgba(255,250,235,.95) 0%, rgba(255,236,200,.6) 32%, rgba(255,214,150,.22) 58%, rgba(255,200,120,0) 78%);
}
.cta-beam::after{
  content:"";position:absolute;left:-230%;top:-55%;width:250%;height:210%;
  background:radial-gradient(ellipse at right center,
    rgba(255,240,205,.34) 0%, rgba(255,226,170,.14) 42%, rgba(255,210,140,0) 74%);
}
.js .cta-rig.in .cta-beam{animation:beamFlash 5s ease-in-out 1.15s infinite}
@keyframes beamFlash{
  0%{opacity:0}
  5%{opacity:1}
  9%{opacity:.12}
  13%{opacity:1}
  20%{opacity:.85}
  30%{opacity:0}
  100%{opacity:0}
}
.ctaband .cta-glow{
  position:absolute;z-index:1;right:clamp(-60px,-2vw,0px);bottom:-26%;
  width:clamp(300px,36vw,560px);aspect-ratio:1/1;border-radius:50%;pointer-events:none;
  background:radial-gradient(circle,rgba(5,104,235,.5) 0%,rgba(5,104,235,0) 68%);
}

@media(max-width:1180px){
  .cta-in{max-width:min(64%,640px)}
  .cta-person{height:clamp(340px,34vw,470px);right:clamp(10px,2vw,40px)}
}
@media(max-width:900px){
  /* van fills the base of the panel, bottom edge flush with the border */
  .cta-rig{left:0;right:0;width:100%;bottom:clamp(62px,7vw,110px)}
  .cta-in{max-width:none;padding-bottom:min(66vw,250px)}
  .ctaband{padding-bottom:clamp(28px,5vw,44px)}
  .ctaband::after{background:linear-gradient(170deg, rgba(6,18,38,.9) 0%, rgba(6,18,38,.72) 48%, rgba(6,18,38,.5) 100%)}
  .ctaband .cta-glow{bottom:-16%;right:-20%;width:84%}
}

/* ==========================================================================
   FOOTER
   ========================================================================== */
footer{background:var(--ink);color:#a9a9b0;padding-top:clamp(54px,6vw,92px)}
.foot-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.15fr;gap:clamp(26px,3.2vw,56px);padding-bottom:clamp(42px,5vw,70px)}
.foot-logo .logo-img{width:min(250px,62vw);background:#fff;border-radius:14px;padding:13px 16px}
.foot-about{margin:22px 0 0;font-size:.98rem;color:#9b9ba2;max-width:42ch}
.fcol h4{color:#fff;margin-bottom:22px;font-size:1.14rem}
.fcol ul{list-style:none;margin:0;padding:0;display:grid;gap:13px}
.fcol a{color:#a9a9b0;font-size:.98rem;transition:.24s}
.fcol a:hover{color:var(--brand-l);padding-left:4px}
.fcontact ul{gap:17px}
.fcontact li{display:flex;gap:12px;align-items:flex-start}
.fcontact svg{width:17px;height:17px;color:var(--brand);margin-top:4px}
.fcontact span{color:#a9a9b0;font-size:.98rem}
.foot-bot{display:flex;justify-content:center;align-items:center;gap:16px;flex-wrap:wrap;padding:26px 0;border-top:1px solid rgba(255,255,255,.1);font-size:.92rem;color:#86868d;text-align:center}
.built{display:inline-flex;align-items:center;gap:8px}
.built b{color:#d9d9dd;font-weight:600}
.built-ico{width:22px;height:22px}
@media(max-width:1100px){.foot-grid{grid-template-columns:1fr 1fr}}
@media(max-width:640px){.foot-grid{grid-template-columns:1fr}}

/* ==========================================================================
   SLIDE-OUT QUOTE PANEL
   ========================================================================== */
.qt-chk{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.qt-tab{
  position:fixed;right:0;top:50%;transform:translateY(-50%);z-index:90;
  display:flex;flex-direction:column;align-items:center;cursor:pointer;transition:.34s var(--ease);
}
.qt-tab__body{
  background:var(--ink);color:#fff;border-radius:14px 0 0 0;padding:24px 11px 26px;
  display:flex;flex-direction:column;align-items:center;
  box-shadow:-12px 0 34px rgba(0,0,0,.3);border:1px solid rgba(255,255,255,.1);border-right:0;
}
.qt-tab__text{
  writing-mode:vertical-rl;text-orientation:mixed;font-family:'Epilogue',Arial,sans-serif;
  font-weight:700;font-size:.86rem;letter-spacing:.15em;text-transform:uppercase;color:#fff;
}
.qt-tab__go{
  width:100%;background:var(--brand);color:#fff;border-radius:0 0 0 14px;padding:15px 0;
  display:flex;align-items:center;justify-content:center;transition:.3s var(--ease);
}
.qt-tab__go svg{width:20px;height:20px;transition:.3s var(--ease)}
.qt-tab:hover .qt-tab__go{background:var(--brand-d);color:#fff}
.qt-tab:hover .qt-tab__go svg{transform:translateX(3px)}
.qt-tab:hover{transform:translateY(-50%) translateX(-4px)}

.qt-panel{
  position:fixed;top:0;right:0;height:100%;width:min(580px,100%);z-index:100;background:var(--ink);
  color:#e9e9ec;transform:translateX(102%);transition:transform .46s var(--ease-out);overflow-y:auto;
  box-shadow:-24px 0 70px rgba(0,0,0,.5);padding:clamp(24px,3vw,38px) clamp(20px,3vw,40px) 52px;
}
.qt-ov{position:fixed;inset:0;z-index:99;background:rgba(4,10,22,.64);backdrop-filter:blur(3px);opacity:0;pointer-events:none;transition:opacity .4s var(--ease)}
.qt-chk:checked ~ .qt-panel{transform:translateX(0)}
.qt-chk:checked ~ .qt-ov{opacity:1;pointer-events:auto}
.qt-chk:checked ~ .qt-tab{opacity:0;pointer-events:none;transform:translateY(-50%) translateX(44px)}
.qt-close{
  position:absolute;top:clamp(20px,2.4vw,28px);right:clamp(20px,2.4vw,28px);width:48px;height:48px;
  border-radius:50%;border:1px solid rgba(255,255,255,.2);display:flex;align-items:center;justify-content:center;
  cursor:pointer;color:#fff;transition:.3s var(--ease);background:rgba(255,255,255,.06);
}
.qt-close svg{width:19px;height:19px}
.qt-close:hover{background:var(--brand);border-color:var(--brand);transform:rotate(90deg)}
.qt-eyebrow{
  display:inline-flex;align-items:center;gap:8px;background:var(--brand);color:#fff;border-radius:var(--pill);
  padding:9px 20px;font-family:'Epilogue',Arial,sans-serif;font-weight:700;font-size:.79rem;
  letter-spacing:.1em;text-transform:uppercase;margin-bottom:20px;
}
.qt-eyebrow svg{width:14px;height:14px}
.qt-panel h2{color:#fff;font-size:clamp(1.6rem,3vw,2.1rem);margin-bottom:20px;max-width:18ch}
.qt-note{border:1px solid rgba(5,104,235,.5);background:rgba(5,104,235,.08);border-radius:var(--r-sm);padding:18px 20px;margin-bottom:28px}
.qt-note p{margin:0;font-size:.98rem;color:#d9d9de}
.qt-note p strong{color:var(--brand-l)}
.qt-note .fine{font-size:.83rem;color:#8e8e96;margin-top:9px;line-height:1.5}
.qt-grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}
.qt-field{display:flex;flex-direction:column;gap:8px;min-width:0}
.qt-field.full{grid-column:1/-1}
.qt-field label{font-family:'Epilogue',Arial,sans-serif;font-weight:700;font-size:.79rem;letter-spacing:.08em;text-transform:uppercase;color:#fff}
.qt-field label i{color:var(--brand);font-style:normal}
.qt-field input,.qt-field select,.qt-field textarea{
  font-family:'DM Sans',Arial,sans-serif;font-size:.98rem;color:#fff;background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.18);border-radius:var(--r-sm);padding:14px 16px;width:100%;
  transition:.22s;appearance:none;
}
.qt-field textarea{min-height:104px;resize:vertical}
.qt-field input::placeholder,.qt-field textarea::placeholder{color:#7a7a82}
.qt-field select{
  background-image:url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%230568eb' stroke-width='2.4' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='m6 9 6 6 6-6'/%3E%3C/svg%3E");
  background-repeat:no-repeat;background-position:right 15px center;background-size:17px;padding-right:42px;
}
.qt-field select option{background:var(--ink);color:#fff}
.qt-field input:focus,.qt-field select:focus,.qt-field textarea:focus{outline:none;border-color:var(--brand);background:rgba(5,104,235,.07)}
.qt-submit{width:100%;margin-top:26px;justify-content:center;font-size:1.03rem;letter-spacing:.04em;text-transform:uppercase;font-weight:700;border-radius:var(--r-sm)}
.qt-or{margin-top:18px;font-size:.94rem;color:#8e8e96;text-align:center}
.qt-or a{color:var(--brand-l);font-weight:600}
@media(max-width:540px){.qt-grid{grid-template-columns:1fr}}
@media(max-width:1200px){
  .qt-tab__text{font-size:.74rem;letter-spacing:.1em}
  .qt-tab__body{padding:16px 9px 18px;border-radius:12px 0 0 0}
  .qt-tab__go{padding:11px 0;border-radius:0 0 0 12px}
  .qt-tab__go svg{width:16px;height:16px}
  .qt-tab{top:auto;bottom:140px;transform:none}
  .qt-tab:hover{transform:translateX(-4px)}
  .qt-chk:checked ~ .qt-tab{transform:translateX(44px)}
}

/* ==========================================================================
   MOBILE BAR + BACK TO TOP
   ========================================================================== */
.mbar{display:none}
@media(max-width:900px){
  .mbar{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:85;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 26px rgba(7,18,36,.1)}
  .mbar a,.mbar label{flex:1;display:flex;align-items:center;justify-content:center;gap:9px;padding:16px 8px;font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:.97rem}
  .mbar .mcall{color:var(--ink);border-right:1px solid var(--line)}
  .mbar .mbook{background:var(--brand);color:#fff}
  body{padding-bottom:60px}
}
.backtop{
  position:fixed;right:18px;bottom:18px;z-index:80;width:50px;height:50px;border-radius:50%;
  background:var(--ink);color:#fff;display:flex;align-items:center;justify-content:center;
  box-shadow:var(--sh);transition:.3s var(--ease);opacity:0;pointer-events:none;transform:translateY(12px);
}
.backtop.show{opacity:1;pointer-events:auto;transform:none}
.backtop:hover{background:var(--brand)}
.backtop svg{width:20px;height:20px}
html:not(.js) .backtop{opacity:1;pointer-events:auto;transform:none}
@media(max-width:900px){.backtop{bottom:74px;right:auto;left:14px;width:44px;height:44px}}

/* ==========================================================================
   MISC
   ========================================================================== */
.bg-soft{background:var(--soft)}
.bg-cream{background:var(--cream)}
.visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}



/* ===== INTERIOR SUBHERO ===== */
.subhero-outer{padding:14px var(--gut) 0;max-width:var(--maxw-wide);margin:0 auto}
.subhero{position:relative;border-radius:var(--r-xl);overflow:hidden;background:var(--ink);isolation:isolate;min-height:clamp(360px,42vw,520px);display:flex;align-items:flex-end}
.subhero-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0;animation:kb 26s ease-in-out infinite alternate}
.subhero::after{content:"";position:absolute;inset:0;z-index:1;background:radial-gradient(70% 70% at 22% 20%,rgba(6,18,38,.5),rgba(6,18,38,0) 70%),radial-gradient(120% 90% at 50% 118%,rgba(5,104,235,.34) 0%,rgba(5,104,235,0) 56%),linear-gradient(180deg,rgba(6,18,38,.52) 0%,rgba(6,18,38,.32) 42%,rgba(6,18,38,.9) 100%)}
.subhero-in{position:relative;z-index:3;width:100%;padding:clamp(40px,5vw,72px) clamp(22px,4vw,70px);max-width:960px}
.crumb{display:flex;flex-wrap:wrap;gap:9px;align-items:center;color:rgba(255,255,255,.66);font-family:'Epilogue',Arial,sans-serif;font-size:.9rem;margin-bottom:20px}
.crumb a{color:rgba(255,255,255,.66);transition:.2s}.crumb a:hover{color:#fff}
.crumb i{color:rgba(255,255,255,.3);font-style:normal}
.crumb b{color:var(--brand-l);font-weight:600}
.subhero h1{color:#fff;max-width:20ch;margin-bottom:.3em}
.subhero .sub{color:rgba(255,255,255,.85);font-size:clamp(1.02rem,1.2vw,1.2rem);max-width:60ch;margin:0 0 30px}
.subhero-cta{display:flex;gap:14px;flex-wrap:wrap;align-items:center}
.subhero-chips{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:22px}
.subhero-chips span{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);backdrop-filter:blur(8px);color:#fff;border-radius:var(--pill);padding:8px 16px;font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:.85rem}
.subhero-chips span svg{width:15px;height:15px;color:var(--brand-l)}

/* ===== SPLIT INTRO (text + media) ===== */
.split{display:grid;grid-template-columns:1fr 1fr;gap:clamp(34px,4.6vw,84px);align-items:center}
.split.wide-text{grid-template-columns:1.1fr .9fr}
.split-media{position:relative;border-radius:var(--r-lg);overflow:hidden;min-height:clamp(320px,34vw,500px)}
.split-media img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .9s var(--ease)}
.split-media:hover img{transform:scale(1.05)}
.split-media .badge{position:absolute;left:clamp(16px,1.6vw,24px);bottom:clamp(16px,1.6vw,24px);z-index:2;background:#fff;border-radius:var(--r-md);padding:16px 20px;box-shadow:var(--sh);display:flex;align-items:center;gap:13px;max-width:280px}
.split-media .badge .bi{width:46px;height:46px;border-radius:12px;background:var(--brand);color:#fff;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.split-media .badge .bi svg{width:22px;height:22px}
.split-media .badge b{display:block;font-family:'Epilogue',Arial,sans-serif;font-size:1.02rem;color:var(--ink);line-height:1.1}
.split-media .badge span{display:block;font-size:.85rem;color:var(--muted);margin-top:2px}
.split-media.ph{min-height:clamp(320px,34vw,500px)}
.split-media.ph img{position:absolute}
.ul-check{list-style:none;margin:24px 0 30px;padding:0;display:grid;gap:14px}
.ul-check li{display:flex;gap:13px;align-items:flex-start;color:var(--ink-2);font-size:1.02rem}
.ul-check li svg{width:24px;height:24px;color:var(--brand);flex-shrink:0;margin-top:1px}
@media(max-width:1000px){.split,.split.wide-text{grid-template-columns:1fr;gap:30px}.split-media{min-height:min(74vw,420px)}.split-rev .split-media{order:-1}}

/* ===== SPEC TABLE ===== */
.spectable{background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden;box-shadow:var(--sh)}
.spectable .row{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:16px clamp(18px,2vw,28px);border-bottom:1px solid var(--line-2);align-items:center}
.spectable .row:last-child{border-bottom:0}
.spectable .row:nth-child(even){background:var(--soft)}
.spectable .row .k{display:flex;align-items:center;gap:11px;color:var(--muted);font-size:.98rem}
.spectable .row .k svg{width:19px;height:19px;color:var(--brand)}
.spectable .row .v{font-family:'Epilogue',Arial,sans-serif;font-weight:600;color:var(--ink);text-align:right}

/* ===== VEHICLE GRID (hub + related) ===== */
.vgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(16px,1.8vw,26px)}
.vcard{background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden;display:flex;flex-direction:column;transition:.44s var(--ease);position:relative}
.vcard:hover{transform:translateY(-10px);box-shadow:var(--sh-lg);border-color:#fff}
.vcard-img{position:relative;aspect-ratio:16/11;overflow:hidden;background:radial-gradient(circle at 50% 60%,var(--brand-soft) 0%,#fff 72%)}
.vcard-img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .8s var(--ease)}
.vcard:hover .vcard-img img{transform:scale(1.07)}
.vcard-tag{position:absolute;top:14px;left:14px;z-index:2;background:rgba(6,18,38,.68);backdrop-filter:blur(8px);color:#fff;border:1px solid rgba(255,255,255,.2);border-radius:var(--pill);padding:6px 14px;font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:.78rem}
.vcard-body{padding:clamp(22px,2vw,30px);display:flex;flex-direction:column;flex:1}
.vcard-body h3{margin:0 0 4px;font-size:1.3rem}
.vcard-sub{color:var(--muted);font-size:.95rem;margin:0 0 16px}
.vcard-specs{list-style:none;margin:0 0 18px;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.vcard-specs li{display:inline-flex;align-items:center;gap:7px;background:var(--soft);border:1px solid var(--line-2);border-radius:var(--pill);padding:6px 13px;font-size:.84rem;color:var(--ink-2)}
.vcard-specs li svg{width:15px;height:15px;color:var(--muted-2)}
.vcard-foot{margin-top:auto;display:flex;align-items:center;justify-content:space-between;gap:12px;padding-top:18px;border-top:1px solid var(--line-2)}
.vcard-price{font-family:'Epilogue',Arial,sans-serif;line-height:1}
.vcard-price .amt{font-size:1.5rem;font-weight:700;color:var(--ink)}
.vcard-price .amt.poa{font-size:1.12rem}
.vcard-price span{display:block;font-size:.8rem;color:var(--muted);margin-top:3px}
@media(max-width:1100px){.vgrid{grid-template-columns:1fr 1fr}}
@media(max-width:640px){.vgrid{grid-template-columns:1fr}}

/* ===== CONTACT ===== */
.contact-grid{display:grid;grid-template-columns:.95fr 1.05fr;gap:clamp(30px,4vw,64px);align-items:start}
.cinfo{display:grid;gap:14px}
.cinfo-item{display:flex;gap:18px;align-items:flex-start;background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);padding:clamp(20px,2vw,28px);transition:.36s var(--ease)}
.cinfo-item:hover{box-shadow:var(--sh);border-color:#fff;transform:translateY(-4px)}
.cinfo-ico{width:56px;height:56px;border-radius:15px;flex-shrink:0;background:var(--brand-soft);color:var(--brand);display:flex;align-items:center;justify-content:center;transition:.36s var(--ease)}
.cinfo-item:hover .cinfo-ico{background:var(--brand);color:#fff}
.cinfo-ico svg{width:24px;height:24px}
.cinfo-item h4{margin:0 0 4px}
.cinfo-item a,.cinfo-item p{color:var(--muted);font-size:1rem;margin:0}
.cinfo-item a:hover{color:var(--brand)}
.cform{background:var(--cream);border:1px solid var(--line);border-radius:var(--r-xl);padding:clamp(26px,3vw,46px)}
.cform h3{margin:0 0 6px}.cform .lead{margin-bottom:24px}
.cform .qt-grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}
.cform .qt-field{display:flex;flex-direction:column;gap:8px;min-width:0}
.cform .qt-field.full{grid-column:1/-1}
.cform .qt-field label{font-family:'Epilogue',Arial,sans-serif;font-weight:700;font-size:.78rem;letter-spacing:.07em;text-transform:uppercase;color:var(--ink)}
.cform .qt-field label i{color:var(--brand);font-style:normal}
.cform .qt-field input,.cform .qt-field select,.cform .qt-field textarea{font-family:'DM Sans',Arial,sans-serif;font-size:.98rem;color:var(--ink-2);background:#fff;border:1.5px solid var(--line);border-radius:var(--r-sm);padding:14px 16px;width:100%;transition:.22s;appearance:none;min-width:0}
.cform .qt-field textarea{min-height:120px;resize:vertical}
.cform .qt-field select{background-image:url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%230568eb' stroke-width='2.4' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='m6 9 6 6 6-6'/%3E%3C/svg%3E");background-repeat:no-repeat;background-position:right 15px center;background-size:17px;padding-right:42px}
.cform .qt-field input:focus,.cform .qt-field select:focus,.cform .qt-field textarea:focus{outline:none;border-color:var(--brand);background:#fff}
.cform .qt-submit{width:100%;margin-top:22px;justify-content:center;text-transform:uppercase;letter-spacing:.04em;font-weight:700;border-radius:var(--r-sm)}
.cmap{margin-top:clamp(40px,4vw,64px);border-radius:var(--r-lg);overflow:hidden;border:1px solid var(--line)}
.cmap img{width:100%;display:block}
@media(max-width:1000px){.contact-grid{grid-template-columns:1fr}.cform .qt-grid{grid-template-columns:1fr}}

/* ===== PRICING / TERMS STRIP ===== */
.terms{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(16px,1.8vw,24px)}
.term{background:#fff;border:1px solid var(--line);border-radius:var(--r-lg);padding:clamp(24px,2.2vw,34px);transition:.4s var(--ease)}
.term:hover{box-shadow:var(--sh);transform:translateY(-6px);border-color:#fff}
.term-ico{width:58px;height:58px;border-radius:15px;background:var(--brand-soft);color:var(--brand);display:flex;align-items:center;justify-content:center;margin-bottom:18px;transition:.4s var(--ease)}
.term:hover .term-ico{background:var(--brand);color:#fff;transform:rotate(-6deg)}
.term-ico svg{width:26px;height:26px}
.term h3{margin:0 0 8px;font-size:1.15rem}.term p{margin:0;color:var(--muted);font-size:.97rem}
@media(max-width:900px){.terms{grid-template-columns:1fr}}

/* generic intro section helper */
.sec-intro{max-width:760px}
.pill-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:8px}
.pill-row span{display:inline-flex;align-items:center;gap:8px;background:var(--cream);border:1px solid var(--line);border-radius:var(--pill);padding:9px 18px;font-family:'Epilogue',Arial,sans-serif;font-weight:600;font-size:.9rem;color:var(--ink)}
.pill-row span svg{width:16px;height:16px;color:var(--brand)}


.ty-wrap{max-width:var(--maxw-wide);margin:0 auto;padding:clamp(20px,3vw,40px) var(--gut) clamp(50px,6vw,90px)}
.ty-card{position:relative;border-radius:var(--r-xl);overflow:hidden;background:var(--ink);isolation:isolate;text-align:center;padding:clamp(44px,6vw,96px) clamp(24px,4vw,70px)}
.ty-card::before{content:"";position:absolute;inset:0;z-index:0;background:radial-gradient(60% 80% at 50% 0%,rgba(5,104,235,.3),rgba(5,104,235,0) 62%),radial-gradient(50% 60% at 90% 100%,rgba(5,104,235,.2),rgba(5,104,235,0) 60%)}
.ty-in{position:relative;z-index:2;max-width:620px;margin:0 auto}
.ty-tick{width:92px;height:92px;border-radius:50%;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);display:flex;align-items:center;justify-content:center;margin:0 auto 26px}
.ty-tick svg{width:46px;height:46px;color:var(--brand-l)}
.ty-card h1{color:#fff;margin-bottom:.4em}
.ty-card p{color:rgba(255,255,255,.8);font-size:1.08rem}
.ty-btns{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:34px}
.ty-phone{display:inline-flex;align-items:center;gap:12px;font-family:'Epilogue',Arial,sans-serif;color:#fff;font-size:clamp(1.3rem,2vw,1.7rem);font-weight:700;margin-top:28px}
.ty-phone .tp-ico{width:52px;height:52px;border-radius:50%;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);display:flex;align-items:center;justify-content:center}
.ty-phone .tp-ico svg{width:20px;height:20px;color:var(--brand-l)}
.ty-note{color:rgba(255,255,255,.55);font-size:.95rem;margin-top:22px}
